{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "구청 주최 축제에서 공원 안 먹거리 판매 같은 상행위 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "구청이 주최하는 축제라면 공원 안에서 먹거리 판매 같은 상행위를 할 수 있습니다. 서울특별시 도시공원 조례 제22조제2항제1호는 국가 또는 지방자치단체 및 공공기관이 주최·주관하는 행사의 상행위를 허용하고 있고, 같은 조례 제2조제1호에 따라 자치구청장은 공원관리청에 해당하므로 구청이 주최하는 행사는 이 허용 대상에 포함됩니다. 다만 같은 조 제2항 본문에 따라 공원관리에 현저한 지장을 초래하지 않는 범위에서만 허용됩니다.",
          "b_ids": "도시공원:제22조제2항, 도시공원:제22조제2항제1호, 도시공원:제2조제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
